	let density = clamp(f.r, 0.0, 4.0);
	let recall = clamp(f.g, 0.0, 4.0);
	let immune = clamp(f.b, 0.0, 4.0);
	let write_glow = clamp(f.a, 0.0, 4.0);
	let centerline = smoothstep(0.44, 0.02, abs(frag.uv.y - 0.5));
